package com.nigson.commerce.promotion;

import java.time.*;
import java.sql.Timestamp;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import io.micrometer.core.instrument.MeterRegistry;
import com.nigson.commerce.platform.*;
import com.nigson.commerce.pricing.PricingAuthority;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ActorAssertion;
import tools.jackson.databind.JsonNode;

/** Versioned promotion commands. Commercial activation requires a matching reviewed configuration record. */
public final class PromotionService {
 private final JdbcTemplate jdbc;private final PlatformStore commands;private final PromotionRepository repository;private final PricingAuthority authority;private final AuditWriter audit;private final Clock clock;private final MeterRegistry metrics;private final int phase;
 public PromotionService(JdbcTemplate jdbc,PlatformStore commands,PricingAuthority authority,AuditWriter audit,Clock clock,MeterRegistry metrics,int phase){this.jdbc=jdbc;this.commands=commands;this.authority=authority;this.audit=audit;this.clock=clock;this.metrics=metrics;this.phase=phase;repository=new PromotionRepository(jdbc,clock);}
 private void enabled(){if(phase<2)throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);}
 private void current(ActorAssertion.Actor actor,String role){enabled();authority.require(actor,role);}
 private void bounds(){jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");}
 @SuppressWarnings("unchecked") private <T>T command(ActorAssertion.Actor actor,String role,String api,String key,Object input,UUID correlation,java.util.function.Supplier<T> change,AuditValues.Action action,AuditValues.Resource resource){current(actor,role);ApiValues.idempotencyKey(key);if(correlation==null||correlation.equals(new UUID(0,0)))throw ApiValues.invalid();try{var response=commands.executeLocal(actor.party().toString(),api,key,EventCodec.JSON.valueToTree(input),db->{bounds();authority.stabilize(actor,role);T value=change.get();UUID id=id(value);audit.append(actor.party().toString(),AuditValues.ActorKind.USER,action,resource,id,correlation,AuditValues.Reason.CONFIGURATION_CHANGE,null,Map.of("operation",api,"changed",true),null);if("API-153".equals(api))event((PromotionValues.Rule)value,actor.party().toString(),correlation);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.promotion.commands","operation",switch(api){case "API-055"->"CREATE_RULE";case "API-152"->"REVISE_RULE";case "API-153"->"ACTIVATE_RULE";case "API-057"->"CREATE_COUPON";case "API-154"->"TOGGLE_COUPON";case "API-059"->"CREATE_CAMPAIGN";case "API-155"->"TOGGLE_CAMPAIGN";default->"DRAW";}).increment();}});return new PlatformStore.Response(Set.of("API-153","API-154","API-155").contains(api)?200:201,EventCodec.JSON.valueToTree(value),id);});return (T)EventCodec.JSON.treeToValue(response.body(),type(api));}catch(org.springframework.dao.DataAccessException failure){for(Throwable cause=failure;cause!=null;cause=cause.getCause())if(cause instanceof java.sql.SQLException sql&&Set.of("55P03","57014").contains(sql.getSQLState()))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_IN_PROGRESS);throw failure;}}
 private static UUID id(Object value){if(value instanceof PromotionValues.Rule r)return r.id();if(value instanceof PromotionValues.Coupon c)return c.id();if(value instanceof PromotionValues.Campaign c)return c.id();if(value instanceof PromotionValues.Draw d)return d.drawId();throw new IllegalArgumentException("PROMOTION_RESOURCE_INVALID");}
 private static Class<?> type(String api){return switch(api){case "API-055","API-152","API-153"->PromotionValues.Rule.class;case "API-057","API-154"->PromotionValues.Coupon.class;case "API-059","API-155"->PromotionValues.Campaign.class;case "API-061"->PromotionValues.Draw.class;default->throw new IllegalArgumentException("PROMOTION_API_INVALID");};}
 public PromotionValues.Page<PromotionValues.Rule> rules(ActorAssertion.Actor a,PromotionValues.Query q){current(a,"SALES");return repository.rules(q);}
 public PromotionValues.Page<PromotionValues.Coupon> coupons(ActorAssertion.Actor a,PromotionValues.Query q){current(a,"SALES");return repository.coupons(q);}
 public PromotionValues.Page<PromotionValues.Campaign> campaigns(ActorAssertion.Actor a,PromotionValues.Query q){current(a,"SALES");return repository.campaigns(q);}
 public PromotionValues.Rule createRule(ActorAssertion.Actor a,PromotionValues.RuleInput in,String key,UUID c){return command(a,"SALES","API-055",key,in,c,()->repository.create(in,a.party().toString()),AuditValues.Action.PROMOTION_CONFIG,AuditValues.Resource.PROMOTION);}
 public PromotionValues.Rule revise(ActorAssertion.Actor a,UUID id,long expected,PromotionValues.RuleInput in,String key,UUID c){if(expected<0||expected==Long.MAX_VALUE)throw ApiValues.invalid();return command(a,"SALES","API-152",key,Map.of("id",id,"version",expected,"body",in),c,()->repository.revise(id,expected,in,a.party().toString()),AuditValues.Action.PROMOTION_CONFIG,AuditValues.Resource.PROMOTION);}
 public PromotionValues.Coupon createCoupon(ActorAssertion.Actor a,PromotionValues.CouponInput in,String key,UUID c){return command(a,"SALES","API-057",key,in,c,()->repository.createCoupon(in,a.party().toString()),AuditValues.Action.PROMOTION_CONFIG,AuditValues.Resource.PROMOTION);}
 public PromotionValues.Campaign createCampaign(ActorAssertion.Actor a,PromotionValues.CampaignInput in,String key,UUID c){return command(a,"SALES","API-059",key,in,c,()->repository.createCampaign(in,a.party().toString()),AuditValues.Action.PROMOTION_CONFIG,AuditValues.Resource.PROMOTION);}
 public PromotionValues.Coupon toggleCoupon(ActorAssertion.Actor a,UUID id,long expected,PromotionValues.CouponToggle in,String key,UUID c){if(expected<0||expected==Long.MAX_VALUE)throw ApiValues.invalid();return command(a,"SALES","API-154",key,Map.of("id",id,"version",expected,"body",in),c,()->repository.toggleCoupon(id,expected,in.active(),a.party().toString()),AuditValues.Action.PROMOTION_CONFIG,AuditValues.Resource.PROMOTION);}
 public PromotionValues.Campaign toggleCampaign(ActorAssertion.Actor a,UUID id,long expected,PromotionValues.CampaignToggle in,String key,UUID c){if(expected<0||expected==Long.MAX_VALUE)throw ApiValues.invalid();return command(a,"SALES","API-155",key,Map.of("id",id,"version",expected,"body",in),c,()->repository.toggleCampaign(id,expected,in.enabled(),a.party().toString()),AuditValues.Action.PROMOTION_CONFIG,AuditValues.Resource.PROMOTION);}
 public PromotionValues.Rule activate(ActorAssertion.Actor a,UUID id,long expected,JsonNode body,String key,UUID correlation){current(a,"FINANCE");if(expected<0||expected==Long.MAX_VALUE)throw ApiValues.invalid();PromotionValues.exact(body,Set.of("enabled","approvalReference","reason"));boolean enable=PromotionValues.bool(body,"enabled");String approval=PromotionValues.code(body,"approvalReference"),reason=PromotionValues.reason(body);return command(a,"FINANCE","API-153",key,Map.of("id",id,"version",expected,"enabled",enable,"approvalReference",approval,"reason",reason),correlation,()->{var rule=repository.rule(id,true);if(rule.version()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);var conf=jdbc.query("SELECT value::text,approved_by FROM commerce.feature_configuration WHERE key=? AND active FOR SHARE",(r,n)->new Object[]{r.getString(1),r.getString(2)},approval);if(conf.size()!=1||conf.getFirst()[1]==null)throw PromotionValues.rule();JsonNode value=EventCodec.JSON.readTree((String)conf.getFirst()[0]);if(!value.isObject()||!id.toString().equals(value.path("promotionRuleId").asString())||rule.revision()!=value.path("promotionRevision").asLong(-1)||!value.path("enabled").asBoolean(false))throw PromotionValues.rule();if(enable&&(!rule.endsAt().isAfter(clock.instant())||!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.market WHERE id=? AND enabled AND code='NG' AND currency_code='NGN')",Boolean.class,rule.marketId()))))throw PromotionValues.rule();if(rule.version()==Long.MAX_VALUE)throw PromotionValues.rule();jdbc.update("UPDATE commerce.promotion_rule SET enabled=?,version=version+1,updated_at=?,updated_by=? WHERE id=? AND version=?",enable,Timestamp.from(clock.instant()),a.party().toString(),id,expected);return repository.rule(id,false);},AuditValues.Action.PROMOTION_ACTIVATION,AuditValues.Resource.PROMOTION);}
 public PromotionValues.Draw draw(ActorAssertion.Actor a,UUID id,UUID market,String key,UUID correlation){if(a==null||a.party()==null)throw new Problem.Failure(ProblemCode.AUTH_REQUIRED);current(a,"CUSTOMER");ApiValues.idempotencyKey(key);var body=EventCodec.JSON.valueToTree(Map.of("campaignId",id,"marketId",market));String businessKey=EventCodec.hash(EventCodec.JSON.valueToTree(Map.of("partyId",a.party(),"requestKey",key)));return command(a,"CUSTOMER","API-061",key,body,correlation,()->repository.draw(id,a.party(),market,businessKey,a.party().toString()),AuditValues.Action.PROMOTION_DRAW,AuditValues.Resource.PROMOTION);}
 private void event(PromotionValues.Rule r,String actor,UUID correlation){var envelope=new LinkedHashMap<String,Object>();envelope.put("event_id",EventCodec.uuid7(clock.instant()));envelope.put("event_type","pricing.changed.v1");envelope.put("schema_version",1);envelope.put("producer","commerce");envelope.put("occurred_at",clock.instant());envelope.put("aggregate_id",r.id());envelope.put("aggregate_version",r.version());envelope.put("organization_id",null);envelope.put("correlation_id",correlation);var span=io.opentelemetry.api.trace.Span.current().getSpanContext();envelope.put("traceparent",span.isValid()?"00-"+span.getTraceId()+"-"+span.getSpanId()+"-"+span.getTraceFlags().asHex():null);envelope.put("payload",Map.of("entity_type","PROMOTION_RULE","entity_id",r.id(),"revision",r.revision(),"market_id",r.marketId()));commands.append(EventCodec.JSON.writeValueAsString(envelope),actor);}
}
